// And groups predicates with the AND operator between them.
func And(predicates ...predicate.RouteTarget) predicate.RouteTarget {
	return predicate.RouteTarget(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.RouteTarget) predicate.RouteTarget {
	return predicate.RouteTarget(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.RouteTarget) predicate.RouteTarget {
	return predicate.RouteTarget(sql.NotPredicates(p))
}
